mapper.select:
SELECT * FROM (SELECT ee.id AS employeeId, ee.employee_code AS employeeCode, CONCAT(ee.last_name, ' ', ee.first_name) AS displayName, CONCAT(ee.last_name_kana, ' ', ee.first_name_kana) AS displayNameKana, ee.email, ee.company_id AS companyId, oc.`name` AS companyName, orn.id AS nodeId, orn.`name` AS nodeName, og.id AS gradeId, og.`name` AS gradeName, ee.phone, ee.gender, og.sort, ROW_NUMBER() OVER (PARTITION BY ee.id ORDER BY eep.is_primary DESC) AS rn FROM emp_employee ee INNER JOIN org_company oc ON oc.id = ee.company_id AND oc.`status` = 1 AND oc.is_deleted = 0 INNER JOIN emp_employee_position eep ON eep.employee_id = ee.id AND eep.`status` = 1 AND eep.is_deleted = 0 AND eep.start_date <= CURDATE() AND (eep.end_date IS NULL OR eep.end_date >= CURDATE()) INNER JOIN org_node orn ON orn.id = eep.node_id AND orn.`status` = 1 AND orn.is_deleted = 0 LEFT JOIN org_grade og ON og.id = eep.grade_id AND og.`status` = 1 AND og.is_deleted = 0 WHERE ee.is_deleted = 0
AND (ee.last_name LIKE CONCAT('%', #{q.keyword}, '%') OR ee.first_name LIKE CONCAT('%', #{q.keyword}, '%') OR ee.employee_code LIKE CONCAT('%', #{q.keyword}, '%'))
AND orn.id=#{q.nodeId}
AND og.id=#{q.gradeId}
AND ee.`status` = #{q.status}
) ranked WHERE ranked.rn = 1 ORDER BY ranked.employeeCode LIMIT #{page}, #{size}

SELECT count(*) FROM (SELECT ee.id AS employeeId, ee.employee_code AS employeeCode, CONCAT(ee.last_name, ' ', ee.first_name) AS displayName, CONCAT(ee.last_name_kana, ' ', ee.first_name_kana) AS displayNameKana, ee.company_id AS companyId, oc.`name` AS companyName, orn.id AS nodeId, orn.`name` AS nodeName, og.id AS gradeId, og.`name` AS gradeName, ee.phone, ee.gender, ROW_NUMBER() OVER (PARTITION BY ee.id ORDER BY eep.is_primary DESC) AS rn FROM emp_employee ee INNER JOIN org_company oc ON oc.id = ee.company_id AND oc.`status` = 1 AND oc.is_deleted = 0 INNER JOIN emp_employee_position eep ON eep.employee_id = ee.id -- ★ 修正 AND eep.`status` = 1 AND eep.is_deleted = 0 AND eep.start_date <= CURDATE() AND (eep.end_date IS NULL OR eep.end_date >= CURDATE()) INNER JOIN org_node orn ON orn.id = eep.node_id AND orn.`status` = 1 AND orn.is_deleted = 0 LEFT JOIN org_grade og ON og.id = eep.grade_id AND og.`status` = 1 AND og.is_deleted = 0 WHERE ee.is_deleted = 0 AND ee.`status` = 1
AND (ee.last_name LIKE CONCAT('%', #{q.keyword}, '%') OR ee.first_name LIKE CONCAT('%', #{q.keyword}, '%') OR ee.employee_code LIKE CONCAT('%', #{q.keyword}, '%'))
AND orn.id=#{q.nodeId}
AND og.id=#{q.gradeId}
AND ee.`status` = #{q.status}
) ranked WHERE ranked.rn = 1
